test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-03-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  // Due dates: 2025-01-29, 2025-02-28, 2025-03-15
  // asOf: 2025-03-20 -> daysOverdue: 50, 20, 5
  const result = overdueInvoices([issued1, issued2, issued3], '2025-03-20');

  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 50);
  assert.equal(result[1].daysOverdue, 20);
  assert.equal(result[2].daysOverdue, 5);
});

